def busca_binaria(v, alvo):
    ini, fim = 0, len(v) - 1
    while ini <= fim:
        meio = (ini + fim) // 2
        if v[meio] == alvo:
            return meio
        if v[meio] < alvo:
            ini = meio + 1
        else:
            fim = meio - 1
    return -1

