function contar_palavras(texto) {
  const contagem = {};
  const palavras = texto.toLowerCase().replace(/[.,!?]/g, '').split(/\s+/).filter(Boolean);
  for (const p of palavras) contagem[p] = (contagem[p] ?? 0) + 1;
  return contagem;
}
